mkitem!{mkimpl!{impl OpenOptions { # [doc = " Creates a blank new set of options ready for configuration."] # [doc = ""] # [doc = " All options are initially set to `false`."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::OpenOptions;"] # [doc = ""] # [doc = " let mut options = OpenOptions::new();"] # [doc = " let file = options.read(true).open(\"foo.txt\");"] # [doc = " ```"] # [cfg_attr (not (test) , rustc_diagnostic_item = "open_options_new")] # [stable (feature = "rust1" , since = "1.0.0")] # [must_use] pub fn new () -> Self { OpenOptions (fs_imp :: OpenOptions :: new ()) } # [doc = " Sets the option for read access."] # [doc = ""] # [doc = " This option, when true, will indicate that the file should be"] # [doc = " `read`-able if opened."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::OpenOptions;"] # [doc = ""] # [doc = " let file = OpenOptions::new().read(true).open(\"foo.txt\");"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn read (& mut self , read : bool) -> & mut Self { self . 0 . read (read) ; self } # [doc = " Sets the option for write access."] # [doc = ""] # [doc = " This option, when true, will indicate that the file should be"] # [doc = " `write`-able if opened."] # [doc = ""] # [doc = " If the file already exists, any write calls on it will overwrite its"] # [doc = " contents, without truncating it."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::OpenOptions;"] # [doc = ""] # [doc = " let file = OpenOptions::new().write(true).open(\"foo.txt\");"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn write (& mut self , write : bool) -> & mut Self { self . 0 . write (write) ; self } # [doc = " Sets the option for the append mode."] # [doc = ""] # [doc = " This option, when true, means that writes will append to a file instead"] # [doc = " of overwriting previous contents."] # [doc = " Note that setting `.write(true).append(true)` has the same effect as"] # [doc = " setting only `.append(true)`."] # [doc = ""] # [doc = " Append mode guarantees that writes will be positioned at the current end of file,"] # [doc = " even when there are other processes or threads appending to the same file. This is"] # [doc = " unlike <code>[seek]\\([SeekFrom]::[End]\\(0))</code> followed by `write()`, which"] # [doc = " has a race between seeking and writing during which another writer can write, with"] # [doc = " our `write()` overwriting their data."] # [doc = ""] # [doc = " Keep in mind that this does not necessarily guarantee that data appended by"] # [doc = " different processes or threads does not interleave. The amount of data accepted a"] # [doc = " single `write()` call depends on the operating system and file system. A"] # [doc = " successful `write()` is allowed to write only part of the given data, so even if"] # [doc = " you're careful to provide the whole message in a single call to `write()`, there"] # [doc = " is no guarantee that it will be written out in full. If you rely on the filesystem"] # [doc = " accepting the message in a single write, make sure that all data that belongs"] # [doc = " together is written in one operation. This can be done by concatenating strings"] # [doc = " before passing them to [`write()`]."] # [doc = ""] # [doc = " If a file is opened with both read and append access, beware that after"] # [doc = " opening, and after every write, the position for reading may be set at the"] # [doc = " end of the file. So, before writing, save the current position (using"] # [doc = " <code>[Seek]::[stream_position]</code>), and restore it before the next read."] # [doc = ""] # [doc = " ## Note"] # [doc = ""] # [doc = " This function doesn't create the file if it doesn't exist. Use the"] # [doc = " [`OpenOptions::create`] method to do so."] # [doc = ""] # [doc = " [`write()`]: Write::write \"io::Write::write\""] # [doc = " [`flush()`]: Write::flush \"io::Write::flush\""] # [doc = " [stream_position]: Seek::stream_position \"io::Seek::stream_position\""] # [doc = " [seek]: Seek::seek \"io::Seek::seek\""] # [doc = " [Current]: SeekFrom::Current \"io::SeekFrom::Current\""] # [doc = " [End]: SeekFrom::End \"io::SeekFrom::End\""] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::OpenOptions;"] # [doc = ""] # [doc = " let file = OpenOptions::new().append(true).open(\"foo.txt\");"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn append (& mut self , append : bool) -> & mut Self { self . 0 . append (append) ; self } # [doc = " Sets the option for truncating a previous file."] # [doc = ""] # [doc = " If a file is successfully opened with this option set to true, it will truncate"] # [doc = " the file to 0 length if it already exists."] # [doc = ""] # [doc = " The file must be opened with write access for truncate to work."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::OpenOptions;"] # [doc = ""] # [doc = " let file = OpenOptions::new().write(true).truncate(true).open(\"foo.txt\");"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn truncate (& mut self , truncate : bool) -> & mut Self { self . 0 . truncate (truncate) ; self } # [doc = " Sets the option to create a new file, or open it if it already exists."] # [doc = ""] # [doc = " In order for the file to be created, [`OpenOptions::write`] or"] # [doc = " [`OpenOptions::append`] access must be used."] # [doc = ""] # [doc = " See also [`std::fs::write()`][self::write] for a simple function to"] # [doc = " create a file with some given data."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " If `.create(true)` is set without `.write(true)` or `.append(true)`,"] # [doc = " calling [`open`](Self::open) will fail with [`InvalidInput`](io::ErrorKind::InvalidInput) error."] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::OpenOptions;"] # [doc = ""] # [doc = " let file = OpenOptions::new().write(true).create(true).open(\"foo.txt\");"] # [doc = " ```"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn create (& mut self , create : bool) -> & mut Self { self . 0 . create (create) ; self } # [doc = " Sets the option to create a new file, failing if it already exists."] # [doc = ""] # [doc = " No file is allowed to exist at the target location, also no (dangling) symlink. In this"] # [doc = " way, if the call succeeds, the file returned is guaranteed to be new."] # [doc = " If a file exists at the target location, creating a new file will fail with [`AlreadyExists`]"] # [doc = " or another error based on the situation. See [`OpenOptions::open`] for a"] # [doc = " non-exhaustive list of likely errors."] # [doc = ""] # [doc = " This option is useful because it is atomic. Otherwise between checking"] # [doc = " whether a file exists and creating a new one, the file may have been"] # [doc = " created by another process (a [TOCTOU] race condition / attack)."] # [doc = ""] # [doc = " If `.create_new(true)` is set, [`.create()`] and [`.truncate()`] are"] # [doc = " ignored."] # [doc = ""] # [doc = " The file must be opened with write or append access in order to create"] # [doc = " a new file."] # [doc = ""] # [doc = " [`.create()`]: OpenOptions::create"] # [doc = " [`.truncate()`]: OpenOptions::truncate"] # [doc = " [`AlreadyExists`]: io::ErrorKind::AlreadyExists"] # [doc = " [TOCTOU]: self#time-of-check-to-time-of-use-toctou"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::OpenOptions;"] # [doc = ""] # [doc = " let file = OpenOptions::new().write(true)"] # [doc = "                              .create_new(true)"] # [doc = "                              .open(\"foo.txt\");"] # [doc = " ```"] # [stable (feature = "expand_open_options2" , since = "1.9.0")] pub fn create_new (& mut self , create_new : bool) -> & mut Self { self . 0 . create_new (create_new) ; self } # [doc = " Opens a file at `path` with the options specified by `self`."] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " This function will return an error under a number of different"] # [doc = " circumstances. Some of these error conditions are listed here, together"] # [doc = " with their [`io::ErrorKind`]. The mapping to [`io::ErrorKind`]s is not"] # [doc = " part of the compatibility contract of the function."] # [doc = ""] # [doc = " * [`NotFound`]: The specified file does not exist and neither `create`"] # [doc = "   or `create_new` is set."] # [doc = " * [`NotFound`]: One of the directory components of the file path does"] # [doc = "   not exist."] # [doc = " * [`PermissionDenied`]: The user lacks permission to get the specified"] # [doc = "   access rights for the file."] # [doc = " * [`PermissionDenied`]: The user lacks permission to open one of the"] # [doc = "   directory components of the specified path."] # [doc = " * [`AlreadyExists`]: `create_new` was specified and the file already"] # [doc = "   exists."] # [doc = " * [`InvalidInput`]: Invalid combinations of open options (truncate"] # [doc = "   without write access, create without write or append access,"] # [doc = "   no access mode set, etc.)."] # [doc = ""] # [doc = " The following errors don't match any existing [`io::ErrorKind`] at the moment:"] # [doc = " * One of the directory components of the specified file path"] # [doc = "   was not, in fact, a directory."] # [doc = " * Filesystem-level errors: full disk, write permission"] # [doc = "   requested on a read-only file system, exceeded disk quota, too many"] # [doc = "   open files, too long filename, too many symbolic links in the"] # [doc = "   specified path (Unix-like systems only), etc."] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::fs::OpenOptions;"] # [doc = ""] # [doc = " let file = OpenOptions::new().read(true).open(\"foo.txt\");"] # [doc = " ```"] # [doc = ""] # [doc = " [`AlreadyExists`]: io::ErrorKind::AlreadyExists"] # [doc = " [`InvalidInput`]: io::ErrorKind::InvalidInput"] # [doc = " [`NotFound`]: io::ErrorKind::NotFound"] # [doc = " [`PermissionDenied`]: io::ErrorKind::PermissionDenied"] # [stable (feature = "rust1" , since = "1.0.0")] pub fn open < P : AsRef < Path > > (& self , path : P) -> io :: Result < File > { self . _open (path . as_ref ()) } fn _open (& self , path : & Path) -> io :: Result < File > { fs_imp :: File :: open (path , & self . 0) . map (| inner | File { inner }) } }}}
